<template>
  <div class="page">
    <h2>数据集构建和管理</h2>
    <el-form v-if="isAdmin" :model="form" inline>
      <el-form-item label="名称"><el-input v-model="form.name" /></el-form-item>
      <el-form-item label="故障类型"><el-input v-model="form.fault_type" /></el-form-item>
      <el-form-item label="系统"><el-input v-model="form.system" /></el-form-item>
      <el-form-item label="PBS 单机产品"><el-select v-model="form.structure_node_id" clearable filterable placeholder="选填：关联结构树节点"><el-option v-for="node in products" :key="node.id" :label="`${node.pbs_code} · ${node.name}`" :value="node.id"/></el-select></el-form-item>
      <el-form-item><input type="file" accept=".csv,.json,.jsonl,.xlsx" @change="form.file=$event.target.files[0]" /><el-button type="primary" @click="upload">上传单个数据集</el-button></el-form-item>
      <el-form-item><input ref="batchInput" type="file" multiple accept=".csv,.json,.jsonl,.xlsx" @change="batchFiles=$event.target.files" /><el-button type="success" :loading="batchLoading" @click="batchUpload">批量导入数据</el-button></el-form-item>
    </el-form>
    <el-card shadow="never" class="filters">
      <el-form :model="filters" inline @submit.prevent="search">
        <el-form-item label="关键字"><el-input v-model="filters.q" clearable placeholder="文件名" @keyup.enter="search" /></el-form-item>
        <el-form-item label="来源"><el-input v-model="filters.source" clearable placeholder="如 offline" /></el-form-item>
        <el-form-item label="系统"><el-input v-model="filters.system" clearable /></el-form-item>
        <el-form-item label="故障类型"><el-input v-model="filters.fault_type" clearable /></el-form-item>
        <el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="resetFilters">清空</el-button></el-form-item>
      </el-form>
    </el-card>
    <el-alert v-if="batchReport" class="batch-report" type="info" :closable="false" :title="`批量导入完成: 成功 ${batchReport.imported}, 失败 ${batchReport.failed}`" />
    <div class="selection-toolbar"><span>当前筛选结果 {{ visibleRows.length }} 条</span></div>
    <el-table :data="visibleRows" row-key="id" v-loading="loading">
      <el-table-column prop="name" label="文件" min-width="210" /><el-table-column prop="source" label="来源" width="100" /><el-table-column prop="fault_type" label="故障类型" min-width="140" /><el-table-column prop="system" label="系统" min-width="110" /><el-table-column label="PBS 关联" min-width="170"><template #default="s">{{s.row.structure_node_name||'未关联'}}</template></el-table-column>
      <el-table-column label="操作" width="360"><template #default="s"><el-button link type="primary" @click="previewDataset(s.row)">查看数据</el-button><el-button link type="primary" @click="download(s.row)">下载 CSV</el-button><el-button v-if="isAdmin" link @click="openRename(s.row)">更改名称</el-button><el-button v-if="isAdmin" link @click="openLink(s.row)">关联 PBS</el-button><el-button v-if="isAdmin" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column>
    </el-table>
    <el-dialog v-model="previewDialog" :title="previewData?.name||'数据预览'" width="min(1100px,94vw)"><div v-loading="previewLoading"><template v-if="previewData"><el-descriptions border :column="2"><el-descriptions-item label="时间字段">{{previewData.quality?.time_column||'未识别'}}</el-descriptions-item><el-descriptions-item label="故障标记字段">{{previewData.quality?.fault_flag_column||'无'}}</el-descriptions-item><el-descriptions-item label="参数列数">{{previewData.quality?.parameter_columns?.length??0}}</el-descriptions-item><el-descriptions-item label="采样点数">{{previewData.quality?.row_count??0}}</el-descriptions-item><el-descriptions-item label="正常 / 故障采样点">{{previewData.quality?.fault_label_summary?.counts?.['0']??0}} / {{previewData.quality?.fault_label_summary?.counts?.['1']??0}}</el-descriptions-item><el-descriptions-item label="首次故障时间戳">{{previewData.quality?.fault_label_summary?.first_fault_time??'无故障标签'}}</el-descriptions-item></el-descriptions><p>预览前 {{previewData.preview?.length||0}} 个采样点，诊断结果由参数计算；FaultFlag 用于核对真值。</p><el-table :data="previewData.preview||[]" height="360"><el-table-column v-for="column in previewData.columns||[]" :key="column" :prop="column" :label="`${column}${previewData.quality?.column_roles?.[column]==='timestamp'?'（时间戳）':previewData.quality?.column_roles?.[column]==='fault_label'?'（故障标签）':''}`" min-width="140"/></el-table></template></div></el-dialog>
    <el-dialog v-model="renameDialog" title="更改数据集名称" width="min(520px,94vw)"><p>当前名称：{{renameTarget?.name}}</p><el-input v-model="renameValue" maxlength="200" show-word-limit placeholder="请输入新的数据集名称" @keyup.enter="saveRename"/><template #footer><el-button @click="renameDialog=false">取消</el-button><el-button type="primary" :loading="renameSaving" @click="saveRename">保存名称</el-button></template></el-dialog>
    <el-dialog v-model="linkDialog" title="关联 PBS 单机产品" width="min(520px,94vw)"><p>数据集：{{linkTarget?.name}}</p><el-select v-model="linkNodeId" clearable filterable placeholder="请选择结构树中的单机产品" style="width:100%"><el-option v-for="node in products" :key="node.id" :label="`${node.pbs_code} · ${node.name}`" :value="node.id"/></el-select><template #footer><el-button @click="linkDialog=false">取消</el-button><el-button type="primary" :loading="linkSaving" @click="saveLink">保存关联</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { isSimulinkDerived } from '../utils/datasetVisibility.js'
const rows=ref([]), products=ref([]), linkDialog=ref(false), linkTarget=ref(null), linkNodeId=ref(null), linkSaving=ref(false), renameDialog=ref(false), renameTarget=ref(null), renameValue=ref(''), renameSaving=ref(false), loading=ref(false), batchLoading=ref(false), batchFiles=ref([]), batchReport=ref(null), isAdmin=ref(false), form=ref({source:'offline'}), filters=ref({q:'',source:'',fault_type:'',system:''})
const visibleRows=computed(()=>rows.value.filter(dataset=>!isSimulinkDerived(dataset)))
const previewDialog=ref(false),previewLoading=ref(false),previewData=ref(null)
async function previewDataset(row){previewDialog.value=true;previewLoading.value=true;previewData.value=null;try{const response=await fetch(`/api/v1/datasets/${row.id}/`,{credentials:'include'});if(!response.ok)throw Error('数据预览加载失败');previewData.value=await response.json()}catch(e){ElMessage.error(e.message)}finally{previewLoading.value=false}}
const csrfHeaders=()=>{const token=document.cookie.split('; ').find(x=>x.startsWith('csrftoken='))?.slice(10);return token?{'X-CSRFToken':decodeURIComponent(token)}:{}}
async function load(){loading.value=true;try{const params=new URLSearchParams({_:`${Date.now()}`});Object.entries(filters.value).forEach(([k,v])=>{if(v)params.set(k,v)});const r=await fetch(`/api/v1/datasets/?${params}`,{credentials:'include',cache:'no-store'});if(!r.ok)throw Error('数据集加载失败');rows.value=await r.json()}finally{loading.value=false}}
function search(){load().catch(e=>ElMessage.error(e.message))}function resetFilters(){filters.value={q:'',source:'',fault_type:'',system:''};search()}
async function upload(){const f=new FormData();Object.entries(form.value).forEach(([k,v])=>v!==undefined&&v!==null&&f.append(k,v));const r=await fetch('/api/v1/datasets/',{method:'POST',credentials:'include',headers:csrfHeaders(),body:f});if(!r.ok)return ElMessage.error('上传失败:权限不足或文件无效');form.value={source:'offline'};await load();ElMessage.success('数据集已上传')}
async function batchUpload(){if(!batchFiles.value?.length)return ElMessage.warning('请先选择一个或多个数据文件');batchLoading.value=true;try{const f=new FormData();[...batchFiles.value].forEach(file=>f.append('files',file));const r=await fetch('/api/v1/datasets/batch-import/',{method:'POST',credentials:'include',headers:csrfHeaders(),body:f});const j=await r.json();if(!r.ok)throw Error(j.detail||'批量导入失败');batchReport.value=j;await load();ElMessage.success(`已导入 ${j.imported} 个数据集`)}catch(e){ElMessage.error(e.message)}finally{batchLoading.value=false}}
function download(row){window.open(`/api/v1/datasets/${row.id}/download/`,'_blank')}
function openRename(row){renameTarget.value=row;renameValue.value=row.name||'';renameDialog.value=true}
async function saveRename(){if(!renameTarget.value||renameSaving.value)return;const name=renameValue.value.trim();if(!name)return ElMessage.warning('请输入数据集名称');renameSaving.value=true;try{const r=await fetch(`/api/v1/datasets/${renameTarget.value.id}/`,{method:'PATCH',credentials:'include',headers:{'Content-Type':'application/json',...csrfHeaders()},body:JSON.stringify({name})});const j=await r.json();if(!r.ok)throw Error(j.detail||'名称修改失败');renameDialog.value=false;await load();ElMessage.success('数据集名称已更新')}catch(e){ElMessage.error(e.message)}finally{renameSaving.value=false}}
function openLink(row){linkTarget.value=row;linkNodeId.value=row.structure_node_id;linkDialog.value=true}
async function saveLink(){if(!linkTarget.value)return;linkSaving.value=true;try{const r=await fetch(`/api/v1/datasets/${linkTarget.value.id}/`,{method:'PATCH',credentials:'include',headers:{'Content-Type':'application/json',...csrfHeaders()},body:JSON.stringify({structure_node_id:linkNodeId.value})});const j=await r.json();if(!r.ok)throw Error(j.detail||'关联失败');linkDialog.value=false;await load();ElMessage.success('PBS 关联已保存')}catch(e){ElMessage.error(e.message)}finally{linkSaving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`将永久删除"${row.name}"及其 CSV 文件。`,'删除数据集',{type:'warning'});const r=await fetch(`/api/v1/datasets/${row.id}/`,{method:'DELETE',credentials:'include',headers:csrfHeaders(),cache:'no-store'});if(!r.ok)throw Error('删除失败');await load();ElMessage.success('数据集已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'删除失败')}}
onMounted(async()=>{try{const [profile,structure]=await Promise.all([fetch('/api/v1/permissions/profile/',{credentials:'include'}),fetch('/api/v1/phm/acceptance/structure/',{credentials:'include'})]);if(profile.ok)isAdmin.value=(await profile.json()).role==='admin';if(structure.ok)products.value=((await structure.json()).results||[]).filter(node=>node.node_type==='product');await load()}catch(e){ElMessage.error(e.message)}})
</script>
<style scoped>.page{max-width:1400px}.el-form{padding:14px;background:#f7f9fc;margin-bottom:18px}.el-form-item{margin-bottom:12px}.el-form-item .el-select{width:260px}.filters{margin-bottom:16px}.batch-report{margin:10px 0}.filters .el-form{background:transparent;padding:0;margin:0}.dataset-help{margin:4px 0 0;color:#718198;font-size:13px}.filter-head{display:flex;gap:16px;align-items:center}.filter-head span{color:#718198;font-size:13px}.selection-toolbar{display:flex;gap:12px;align-items:center;margin:12px 0;color:#60728a}.selection-toolbar span{margin-right:auto}</style>
